  if (isCircuitOpen) {
    console.log("[Supabase CircuitBreaker] Supabase is back online.");
  }
  isCircuitOpen = false;
  nextProbeTime = 0;
  try {
    if (fs.existsSync(FLAG_FILE)) fs.unlinkSync(FLAG_FILE);
  } catch {}
